import { Component, computed, signal } from '@angular/core';
import { NgTemplateOutlet } from '@angular/common';
import { TranslateModule } from '@ngx-translate/core';
import { NzTableModule } from 'ng-zorro-antd/table';
import { TablerIconComponent, IconChevronRight } from '@tabler/icons-angular';
import { HrmUserCell, HrmAmountCell } from 'hrm-ui';
import { SgDoc } from '../../../doc/sg-doc';
import { SgUse, SgDo, SgDont, SgExample } from '../../../doc/sg-blocks';

interface OrgNode { key: string; name: string; head: string; count: number; children?: OrgNode[]; }
interface FlatRow { key: string; name: string; head: string; count: number; level: number; hasChildren: boolean; }

/** Doc page · Tree List — lưới CÂY có cột (Kendo TreeList): dữ liệu tự-phân-cấp cha-con
 *  hiển thị dạng bảng có cột, mỗi dòng cha mở/gập. Song ngữ qua i18n docs.treeList.*. */
@Component({
  selector: 'sg-doc-tree-list',
  imports: [NgTemplateOutlet, TranslateModule, NzTableModule, TablerIconComponent, HrmUserCell, HrmAmountCell, SgDoc, SgUse, SgDo, SgDont, SgExample],
  template: `
    <sg-doc category="Table & List" [title]="'docs.treeList.title' | translate" [desc]="'docs.treeList.desc' | translate"
      [related]="[{label:'User Cell', route:'hrm/table-cells/user'},{label:'Amount Cell', route:'hrm/table-cells/amount'}]">

      <div sgOverview>
        <div style="width:100%">
          <ng-container [ngTemplateOutlet]="grid" />
        </div>
      </div>

      <div sgUsage>
        <sg-use [purpose]="'docs.treeList.purpose' | translate" [when]="when"
          [behavior]="'docs.treeList.behavior' | translate"
          [avoid]="'docs.treeList.avoid' | translate" />
      </div>

      <div sgBest>
        <sg-do>{{ 'docs.treeList.do1' | translate }}</sg-do>
        <sg-do>{{ 'docs.treeList.do2' | translate }}</sg-do>
        <sg-dont>{{ 'docs.treeList.dont1' | translate }}</sg-dont>
      </div>

      <div sgExamples>
        <sg-example [title]="'docs.treeList.exT' | translate"
          [desc]="'docs.treeList.exD' | translate">
          <div style="width:100%">
            <ng-container [ngTemplateOutlet]="grid" />
          </div>
        </sg-example>
      </div>

      <ng-template #grid>
        <nz-table [nzData]="visible()" [nzShowPagination]="false" nzSize="small">
          <thead><tr><th>{{ 'docs.treeList.colUnit' | translate }}</th><th>{{ 'docs.treeList.colHead' | translate }}</th><th style="text-align:right">{{ 'docs.treeList.colCount' | translate }}</th></tr></thead>
          <tbody>
            @for (r of visible(); track r.key) {
              <tr>
                <td>
                  <span [style.padding-left.px]="r.level * 22" style="display:inline-flex;align-items:center;gap:6px">
                    @if (r.hasChildren) {
                      <button type="button" class="tl-toggle" [class.open]="isOpen(r.key)" (click)="toggle(r.key)" [attr.aria-label]="'docs.treeList.ariaToggle' | translate">
                        <tabler-icon [icon]="chev" [size]="14" />
                      </button>
                    } @else { <span class="tl-dot"></span> }
                    {{ r.name | translate }}
                  </span>
                </td>
                <td><hrm-user-cell [name]="r.head" [colorful]="true" [avatarSize]="30" /></td>
                <td style="text-align:right"><hrm-amount-cell [value]="r.count" /></td>
              </tr>
            }
          </tbody>
        </nz-table>
      </ng-template>

    </sg-doc>
  `,
  styles: [`
    .tl-toggle { display:grid; place-items:center; width:20px; height:20px; border:0; background:transparent; cursor:pointer; color:var(--text-sub); border-radius:var(--radius-sm); }
    .tl-toggle:hover { background:var(--bg-surface-subtle); color:var(--text-strong); }
    .tl-toggle tabler-icon { transition: transform var(--duration-fast,.15s) var(--ease-out,ease); }
    .tl-toggle.open tabler-icon { transform: rotate(90deg); }
    .tl-dot { width:20px; display:inline-block; }
  `],
})
export class SgDocTreeList {
  protected readonly chev = IconChevronRight;
  private readonly tree: OrgNode[] = [
    { key: 'vnr', name: 'docs.treeList.nodeVnr', head: 'Đặng Vũ', count: 1596, children: [
      { key: 'hr', name: 'docs.treeList.nodeHr', head: 'Trần Thu Hà', count: 45, children: [
        { key: 'rec', name: 'docs.treeList.nodeRec', head: 'Lê Quốc Bảo', count: 12 },
        { key: 'cb', name: 'docs.treeList.nodeCb', head: 'Phạm Ngọc Anh', count: 18 },
      ] },
      { key: 'it', name: 'docs.treeList.nodeIt', head: 'Nguyễn Minh Tuấn', count: 98, children: [
        { key: 'be', name: 'docs.treeList.nodeBe', head: 'Đỗ Văn Nam', count: 40 },
        { key: 'fe', name: 'docs.treeList.nodeFe', head: 'Bùi Hải Yến', count: 35 },
      ] },
      { key: 'fin', name: 'docs.treeList.nodeFin', head: 'Võ Thành Trung', count: 60 },
    ] },
  ];
  private readonly open = signal<Set<string>>(new Set(['vnr', 'hr', 'it']));

  protected isOpen(key: string): boolean { return this.open().has(key); }
  protected toggle(key: string): void {
    const s = new Set(this.open());
    s.has(key) ? s.delete(key) : s.add(key);
    this.open.set(s);
  }

  protected readonly visible = computed<FlatRow[]>(() => {
    const openSet = this.open();
    const out: FlatRow[] = [];
    const walk = (nodes: OrgNode[], level: number) => {
      for (const n of nodes) {
        const hasChildren = !!n.children?.length;
        out.push({ key: n.key, name: n.name, head: n.head, count: n.count, level, hasChildren });
        if (hasChildren && openSet.has(n.key)) walk(n.children!, level + 1);
      }
    };
    walk(this.tree, 0);
    return out;
  });

  protected readonly when = ['docs.treeList.when1', 'docs.treeList.when2'];
}
